CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', phone text, preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_self ON public.profiles FOR ALL TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')); RETURN NEW; END $$;
CREATE TRIGGER create_customer_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','admin','operations','support','catalogue')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.staff_has_role(allowed text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=ANY(allowed)) $$;
REVOKE ALL ON FUNCTION public.staff_has_role(text[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.staff_has_role(text[]) TO authenticated;
CREATE TABLE public.categories(id text PRIMARY KEY, name text NOT NULL, image_key text NOT NULL DEFAULT 'headphones', active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.categories TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_categories ON public.categories FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY staff_categories ON public.categories FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','catalogue'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','catalogue']));
CREATE TABLE public.products(id text PRIMARY KEY, name text NOT NULL, sku text NOT NULL UNIQUE, category_id text REFERENCES public.categories(id), description text NOT NULL DEFAULT '', price_paise integer NOT NULL CHECK(price_paise>=0), image_key text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','archived')), fulfillment_model text NOT NULL DEFAULT 'OWN_INVENTORY' CHECK(fulfillment_model IN ('OWN_INVENTORY','DROPSHIP')), is_demo boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
CREATE POLICY active_products ON public.products FOR SELECT TO anon,authenticated USING(status='active');
CREATE POLICY staff_products ON public.products FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','catalogue'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','catalogue']));
CREATE INDEX products_category_idx ON public.products(category_id,status);
CREATE TABLE public.product_variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id text NOT NULL REFERENCES public.products(id),name text NOT NULL,sku text NOT NULL UNIQUE,price_paise integer NOT NULL CHECK(price_paise>=0),active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.product_variants TO anon,authenticated; GRANT INSERT,UPDATE,DELETE ON public.product_variants TO authenticated; GRANT ALL ON public.product_variants TO service_role;
ALTER TABLE public.product_variants ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_variants ON public.product_variants FOR SELECT TO anon,authenticated USING(active AND EXISTS(SELECT 1 FROM public.products p WHERE p.id=product_id AND p.status='active'));
CREATE POLICY staff_variants ON public.product_variants FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','catalogue'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','catalogue']));
CREATE TABLE public.inventory(product_id text PRIMARY KEY REFERENCES public.products(id),quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0),reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=quantity));
GRANT SELECT,INSERT,UPDATE ON public.inventory TO authenticated; GRANT ALL ON public.inventory TO service_role;
ALTER TABLE public.inventory ENABLE ROW LEVEL SECURITY;
CREATE POLICY inventory_staff ON public.inventory FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations','catalogue'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','operations','catalogue']));
CREATE TABLE public.wishlist(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,product_id text NOT NULL REFERENCES public.products(id),PRIMARY KEY(user_id,product_id));
GRANT SELECT,INSERT,DELETE ON public.wishlist TO authenticated; GRANT ALL ON public.wishlist TO service_role;
ALTER TABLE public.wishlist ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_wishlist ON public.wishlist FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.cart_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,product_id text NOT NULL REFERENCES public.products(id),quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 20),UNIQUE(user_id,product_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cart_items TO authenticated; GRANT ALL ON public.cart_items TO service_role;
ALTER TABLE public.cart_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_cart ON public.cart_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,name text NOT NULL,phone text NOT NULL CHECK(phone~'^[6-9][0-9]{9}$'),line1 text NOT NULL,city text NOT NULL,state text NOT NULL,pincode text NOT NULL CHECK(pincode~'^[1-9][0-9]{5}$'),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.addresses TO authenticated; GRANT ALL ON public.addresses TO service_role;
ALTER TABLE public.addresses ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_addresses ON public.addresses FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES public.profiles(id),status text NOT NULL DEFAULT 'pending_payment',payment_status text NOT NULL DEFAULT 'pending',total_paise integer NOT NULL CHECK(total_paise>=0),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role;
ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_orders ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY staff_orders ON public.orders FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations','support']));
CREATE TABLE public.support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id),subject text NOT NULL CHECK(length(subject) BETWEEN 1 AND 120),message text NOT NULL CHECK(length(message) BETWEEN 1 AND 3000),status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.support_tickets TO authenticated; GRANT ALL ON public.support_tickets TO service_role;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_ticket_read ON public.support_tickets FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY own_ticket_create ON public.support_tickets FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='open');
CREATE POLICY staff_ticket_read ON public.support_tickets FOR SELECT TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','support']));
CREATE TABLE public.suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,contact_email text,approved boolean NOT NULL DEFAULT false,manual_fulfillment boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.suppliers TO authenticated; GRANT ALL ON public.suppliers TO service_role;
ALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_suppliers ON public.suppliers FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','operations']));
CREATE TABLE public.supplier_products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),supplier_id uuid NOT NULL REFERENCES public.suppliers(id),product_id text NOT NULL REFERENCES public.products(id),supplier_sku text NOT NULL,cost_paise integer NOT NULL CHECK(cost_paise>=0),available boolean NOT NULL DEFAULT false,dispatch_sla_days integer,return_rules text,UNIQUE(supplier_id,product_id));
GRANT SELECT,INSERT,UPDATE ON public.supplier_products TO authenticated; GRANT ALL ON public.supplier_products TO service_role;
ALTER TABLE public.supplier_products ENABLE ROW LEVEL SECURITY;
CREATE POLICY staff_supplier_products ON public.supplier_products FOR ALL TO authenticated USING(public.staff_has_role(ARRAY['owner','admin','operations'])) WITH CHECK(public.staff_has_role(ARRAY['owner','admin','operations']));
INSERT INTO public.categories(id,name,image_key,sort_order) VALUES ('home','Home & Living','lamp',1),('fashion','Fashion & Accessories','tote',2),('gadgets','Mobile & Desk','headphones',3),('travel','Travel & Lifestyle','organizer',4),('personal','Personal Care','bottle',5),('stationery','Stationery','notebooks',6);
INSERT INTO public.products(id,name,sku,category_id,description,price_paise,image_key,status,is_demo) VALUES ('mint-headphones','Everyday Wireless Headphones','DEMO-A01','gadgets','A little quiet, in your favourite colour. This demonstration product illustrates the store experience; specifications and stock await merchant verification.',199900,'headphones','active',true),('mushroom-lamp','The Little Mushroom Lamp','DEMO-H01','home','A softer glow for your favourite corner. Demonstration catalogue item; final materials, electrical specifications and availability require verification.',129900,'lamp','active',true),('everyday-tote','Your Everyday Tote','DEMO-F01','fashion','For little errands and big days. Demonstration catalogue item; final materials and dimensions await verification.',69900,'tote','active',true),('blue-bottle','Everyday Water Bottle','DEMO-P01','personal','A fresh companion for your daily routine. Demonstration catalogue item; final capacity and materials await verification.',49900,'bottle','active',true),('travel-organizer','The Go-Anywhere Organizer','DEMO-T01','travel','A place for your everyday essentials. Demonstration catalogue item; final dimensions and stock await verification.',59900,'organizer','active',true),('notebook-set','Fresh Start Notebook Set','DEMO-S01','stationery','Make a little room for your next idea. Demonstration catalogue item; page counts and materials await verification.',44900,'notebooks','active',true);